const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const roi = ee.Geometry.Point([14.280, 13.550]).buffer(5000); // Digangali, Chad, 5km buffer
    const date1_start = '2021-09-18';
    const date1_end = '2021-09-19';
    const date2_start = '2022-10-23';
    const date2_end = '2022-10-24';

    // 2. Data Acquisition & Processing Function
    const s2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED');

    // Cloud masking function for Sentinel-2
    function maskS2clouds(image) {
        const qa = image.select('QA60');
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(
                     qa.bitwiseAnd(cirrusBitMask).eq(0));
        return image.updateMask(mask).divide(10000)
                    .select("B.*")
                    .copyProperties(image, ["system:time_start"]);
    }

    // Function to calculate NDWI and create a water mask
    const addWaterMask = function(image) {
        const ndwi = image.normalizedDifference(['B3', 'B8']).rename('ndwi'); // Green and NIR
        const waterMask = ndwi.gt(0.1); // Using a threshold > 0 to be more selective for water
        return image.addBands(waterMask.rename('water'));
    };

    // Process data for a given date range
    async function getWaterArea(startDate, endDate, label) {
        let collection = s2.filterBounds(roi)
                           .filterDate(startDate, endDate);

        let colSize = collection.size().getInfo();
        if (colSize === 0) {
            console.log(`No images found for ${label}.`);
            return {area: null, pixelCount: null, error: 'C1'};
        }

        let image = collection.map(maskS2clouds).map(addWaterMask).median().clip(roi);

        // Check for valid pixels after masking
        const pixelCheck = image.select('water').reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: roi,
            scale: 1000,
            maxPixels: 1e9
        });
        const validPixels = ee.Number(pixelCheck.get('water')).getInfo();

        if (validPixels === 0) {
            console.log(`No valid (non-cloudy) pixels for ${label}.`);
            return {area: null, pixelCount: 0, error: 'C2'};
        }

        const waterImage = image.select('water').selfMask(); // Mask out non-water pixels
        const waterArea = waterImage.multiply(ee.Image.pixelArea()).reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: roi,
            scale: 30, // Use a finer scale for area calculation
            maxPixels: 1e9
        });

        const areaSqKm = ee.Number(waterArea.get('water')).divide(1e6).getInfo();
        return {area: areaSqKm, pixelCount: validPixels, error: null};
    }

    // 3. Calculation
    const result1 = await getWaterArea(date1_start, date1_end, 'Sep 2021');
    const result2 = await getWaterArea(date2_start, date2_end, 'Oct 2022');

    if (result1.error || result2.error) {
        const errorCode = result1.error || result2.error;
        console.log(`Data acquisition failed. Reason: ${errorCode}`);
        console.log(errorCode);
        return;
    }

    // 4. Validation & Final Answer
    console.log(`Sep 2021 Water Area (km^2): ${result1.area !== null ? result1.area.toFixed(2) : 'N/A'}`);
    console.log(`Sep 2021 Valid Pixels: ${result1.pixelCount}`);
    console.log(`Oct 2022 Water Area (km^2): ${result2.area !== null ? result2.area.toFixed(2) : 'N/A'}`);
    console.log(`Oct 2022 Valid Pixels: ${result2.pixelCount}`);

    if (result1.area === null || result2.area === null) {
        console.log("Calculation failed, one or both results are null.");
        console.log('C3');
        return;
    }

    if (result2.area > result1.area) {
        console.log("Water extent increased.");
        console.log('A');
    } else {
        console.log("Water extent did not increase.");
        console.log('B');
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error('An error occurred during EE initialization or analysis:', e);
        console.log('D');
    }
}

initEE();
